    sse_encode_list_weather_day(self.daily, serializer);
    sse_encode_list_weather_alert(self.alerts, serializer);
  }

  @protected
  void sse_encode_workspace_snapshot(
    WorkspaceSnapshot self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.label, serializer);
    sse_encode_bool(self.isFocused, serializer);
    sse_encode_bool(self.isVisible, serializer);
  }
}
